        frFR = "Historique : la nouvelle vue « Quêtes par zone » montre les quêtes terminées et celles que vos autres personnages y ont déjà faites.",
        esES = "Historial: la nueva vista «Misiones por zona» muestra las misiones hechas y las que tus otros personajes ya hicieron allí." },
      { kind = "new",
        deDE = "Rechtsklick auf einen Questpunkt der Weltkarte oder im Questlog fokussiert eine Quest: andere Punkte werden blass, ein Pfeil (Option) führt zu ihr.",
        enUS = "Right-click a quest spot on the world map or in the quest log to focus a quest: other spots fade and an arrow (option) guides you there.",
