        esES = "Clic derecho en un punto de misión del mapa o en el registro enfoca una misión: los demás puntos se atenúan y una flecha (opción) te guía." },
      { kind = "new",
        deDE = "Dungeon-Eingänge auf der Weltkarte zeigen Schlüssel- und Einstimmungs-Questreihen (Schwarzfels, Scholomance, Geschmolzener Kern, Onyxia) mit Stand und nächstem Schritt.",
        enUS = "Dungeon entrances on the world map show key and attunement quest chains (Blackrock, Scholomance, Molten Core, Onyxia) with progress and the next step.",
        frFR = "Les entrées de donjon sur la carte du monde affichent les suites de quêtes de clé et d'accès (Rochenoire, Scholomance, Cœur du Magma, Onyxia) avec la progression et l'étape suivante.",
        esES = "Las entradas de mazmorra en el mapa del mundo muestran las cadenas de misiones de llave y sintonización (Roca Negra, Scholomance, Núcleo de Magma, Onyxia) con el progreso y el siguiente paso." },
      { kind = "fix",
        deDE = "Französischer Client: Einige Boss- und Flugstreckennamen zeigten „u00a0“ statt eines Leerzeichens.",
        enUS = "French client: some boss and flight path names showed \"u00a0\" instead of a space.",
        frFR = "Client français : certains noms de boss et de trajets aériens affichaient « u00a0 » au lieu d'une espace.",
        esES = "Cliente francés: algunos nombres de jefes y rutas de vuelo mostraban «u00a0» en lugar de un espacio." },
      { kind = "new",
        deDE = "WoW Forever: Der Tooltip einer Gruppe in der Gruppensuche zeigt, in welcher Zone die Spieler gerade sind.",
        enUS = "WoW Forever: a group's tooltip in the group finder shows which zone its players are currently in.",
        frFR = "WoW Forever : dans la recherche de groupe, l'infobulle d'un groupe indique dans quelle zone se trouvent ses joueurs.",
        esES = "WoW Forever: en el buscador de grupos, el tooltip de un grupo muestra en qué zona están sus jugadores." },
      { kind = "fix",
        deDE = "Datentext-Leisten und das Addon-Menü reagieren auf alle Klicks wie der Minimap-Knopf; /lt help nennt alle Befehle.",
        enUS = "Data text bars and the addon menu react to every click like the minimap button; /lt help lists all commands.",
        frFR = "Les barres de texte et le menu des addons réagissent à chaque clic comme le bouton de la minicarte ; /lt help liste toutes les commandes.",
        esES = "Las barras de texto y el menú de addons responden a cada clic como el botón del minimapa; /lt help muestra todos los comandos." },
      { kind = "change",
        deDE = "Einheitliche Begriffe: Dungeon-Run, Speedrun-Läufe, Live-Tracker, Layout bearbeiten, Rare und Quest-Automatik.",
        enUS = "Settings: the quest options section is now called \"Quest automation\"; German terms were unified.",
        frFR = "Options : la section des quêtes s'appelle désormais « Automatisation des quêtes » ; termes allemands harmonisés.",
        esES = "Opciones: la sección de misiones se llama ahora «Automatización de misiones»; términos alemanes unificados." },
