        frFR = "WoW Forever : plus de butin de boss affiché et de nombreux objets sont désormais confirmés pour Forever (moins d'astérisques gris).",
        esES = "WoW Forever: se muestra más botín de jefes y muchos objetos ya están confirmados para Forever (menos asteriscos grises)." },
      { kind = "new",
        deDE = "WoW Forever: Hall of Thanes mit Tipps zu allen vier Bossen (jetzt auch Magmatus) und zu gefährlichem Trash.",
        enUS = "WoW Forever: Hall of Thanes now has tips for all four bosses (including Magmatus) and its dangerous trash.",
        frFR = "WoW Forever : Hall of Thanes a désormais des conseils pour les quatre boss (dont Magmatus) et ses monstres dangereux.",
        esES = "WoW Forever: Hall of Thanes ahora tiene consejos para los cuatro jefes (incluido Magmatus) y sus enemigos peligrosos." },
      { kind = "change",
        deDE = "WoW Forever: Dungeon-Levelbereiche aktualisiert (z. B. Deadmines, Uldaman, Dire Maul) und viele neue oder für Forever bestätigte Fähigkeiten-Tipps, von Ragefire Chasm bis Stratholme.",
        enUS = "WoW Forever: updated dungeon level ranges (e.g. Deadmines, Uldaman, Dire Maul) and many new or Forever-confirmed ability tips, from Ragefire Chasm to Stratholme.",
        frFR = "WoW Forever : tranches de niveau des donjons mises à jour (p. ex. Deadmines, Uldaman, Dire Maul) et de nombreux conseils de techniques nouveaux ou confirmés pour Forever, de Ragefire Chasm à Stratholme.",
        esES = "WoW Forever: rangos de nivel de mazmorras actualizados (p. ej. Deadmines, Uldaman, Dire Maul) y muchos consejos de habilidades nuevos o confirmados para Forever, de Ragefire Chasm a Stratholme." },
      { kind = "change",
        deDE = "WoW Forever: Fähigkeiten-Tipps und Bossbeute markieren aus Classic übernommene Zeilen gleich mit einem Sternchen samt Erklärung; Fähigkeiten-Tipps folgen der eingestellten Addon-Sprache.",
        enUS = "WoW Forever: ability tips and boss loot mark lines taken from Classic the same way, with an asterisk and an explanation; ability tips follow the addon language setting.",
        frFR = "WoW Forever : les conseils de techniques et le butin des boss signalent de la même façon les lignes reprises de Classic, avec un astérisque et une explication ; les conseils suivent la langue choisie pour l'addon.",
        esES = "WoW Forever: los consejos de habilidades y el botín de jefes marcan igual las líneas tomadas de Classic, con un asterisco y una explicación; los consejos siguen el idioma elegido para el addon." },
      { kind = "change",
        deDE = "Alle Dungeon-Einstellungen (Dungeonquests, Eingänge, Tooltip, Live-Tracker, Instanzbericht) liegen jetzt gesammelt unter Komfort > Dungeons.",
        enUS = "All dungeon settings (dungeon quests, entrances, tooltip, live tracker, instance report) are now gathered under Comfort > Dungeons.",
        frFR = "Tous les réglages de donjon (quêtes de donjon, entrées, infobulle, suivi en direct, rapport d'instance) sont désormais réunis sous Confort > Donjons.",
        esES = "Todos los ajustes de mazmorras (misiones de mazmorra, entradas, tooltip, seguimiento en directo, informe de instancia) están ahora reunidos en Comodidad > Mazmorras." },
      { kind = "fix",
        deDE = "Rechtsklick auf Schwungbalken und Reichweiten-Anzeige öffnet wieder ihre Einstellungen; das Änderungsprotokoll schließt mit Esc.",
        enUS = "Right-clicking the swing timer and the range display opens their settings again; the changelog closes with Esc.",
        frFR = "Un clic droit sur le minuteur de coups et l'affichage de portée ouvre à nouveau leurs réglages ; le journal des modifications se ferme avec Échap.",
        esES = "Hacer clic derecho en el temporizador de golpes y el indicador de distancia vuelve a abrir sus ajustes; el registro de cambios se cierra con Esc." },
      { kind = "change",
        deDE = "WoW Forever: Fähigkeiten-Tipps im Tooltip passen zu Forever, neu für Stadt Dalaran, Ausgrabungsstätte: Sumpfland, Hallen der Thane und Ruinen von Lordaeron; nur aus Classic übernommene Tipps sind grau markiert.",
        enUS = "WoW Forever: ability tips in tooltips match Forever, new for City of Dalaran, Excavation Site: Wetlands, Hall of Thanes and Ruins of Lordaeron; tips only taken from Classic are marked in grey.",
        frFR = "WoW Forever : les conseils de techniques dans les infobulles correspondent à Forever, nouveaux pour Cité de Dalaran, Site de fouilles : les Paluns, Salle des Thanes et Ruines de Lordaeron ; les conseils repris uniquement de Classic sont signalés en gris.",
        esES = "WoW Forever: los consejos de habilidades en los tooltips coinciden con Forever, nuevos para Ciudad de Dalaran, Excavación: Los Humedales, Sala de los Thanes y Ruinas de Lordaeron; los consejos tomados solo de Classic se marcan en gris." },
      { kind = "new",
        deDE = "WoW Forever: Bosse der Forever-Dungeons zeigen ihre Beute, Bossbeute insgesamt vollständiger (z. B. Rhahk'Zors Hammer); aus Classic übernommene, für Forever unbestätigte Drops tragen ein graues Sternchen.",
        enUS = "WoW Forever: bosses of the Forever dungeons show their loot, boss loot is more complete overall (e.g. Rhahk'Zor's Hammer); drops taken from Classic and unconfirmed for Forever carry a grey asterisk.",
        frFR = "WoW Forever : les boss des donjons Forever affichent leur butin, le butin des boss est plus complet (p. ex. le Marteau de Rhahk'Zor) ; les objets repris de Classic et non confirmés pour Forever portent un astérisque gris.",
        esES = "WoW Forever: los jefes de las mazmorras Forever muestran su botín, el botín de jefes es más completo (p. ej. el Martillo de Rhahk'Zor); los objetos tomados de Classic y sin confirmar para Forever llevan un asterisco gris." },
      { kind = "fix",
        deDE = "Classic Era und WoW Forever: Dungeonquest-Hinweise nennen den Namen des Questgebers, auch bevor du mit ihm gesprochen hast; Objekt-Tooltips aktualisieren sich beim direkten Wechsel zwischen zwei Objekten.",
        enUS = "Classic Era and WoW Forever: dungeon quest hints name the quest giver even before you have talked to them; object tooltips update when moving directly from one object to another.",
        frFR = "Classic Era et WoW Forever : les indications de quêtes de donjon nomment le donneur de quête même avant de lui avoir parlé ; les infobulles d'objets se mettent à jour en passant directement d'un objet à l'autre.",
        esES = "Classic Era y WoW Forever: las indicaciones de misiones de mazmorra nombran al instructor de la misión incluso antes de hablar con él; los tooltips de objetos se actualizan al pasar directamente de un objeto a otro." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Bosszeilen im Run-Fenster und die Live-Karte (nächster Boss) zeigen Beute-Symbole; Drüberfahren zeigt die Gegenstandsinfo.",
        enUS = "Classic Era and WoW Forever: boss rows in the runs window and the live card (next boss) show loot icons; hovering one shows the item tooltip.",
        frFR = "Classic Era et WoW Forever : les lignes de boss de la fenêtre des donjons et la carte en direct (boss suivant) affichent les icônes du butin ; le survol affiche l'infobulle de l'objet.",
        esES = "Classic Era y WoW Forever: las filas de jefe de la ventana de mazmorras y la tarjeta en directo (siguiente jefe) muestran iconos del botín; al pasar el ratón se ve la información del objeto." },
      { kind = "fix",
        deDE = "Classic Era und WoW Forever: Mehr Bossbeute (u. a. Sapphiron, Majordomus Exekutus, die Zul'Gurub-Randbosse), Questgeber der Horde am richtigen Ort und Quests mit mehreren Dungeons nennen alle.",
        enUS = "Classic Era and WoW Forever: more boss loot (including Sapphiron, Majordomo Executus, the optional Zul'Gurub bosses), Horde quest givers at the right place, and quests for several dungeons name all of them.",
        frFR = "Classic Era et WoW Forever : plus de butin de boss (dont Saphiron, Majordome Executus, les boss optionnels de Zul'Gurub), donneurs de quêtes de la Horde au bon endroit, et les quêtes de plusieurs donjons les nomment tous.",
        esES = "Classic Era y WoW Forever: más botín de jefes (entre ellos Sapphiron, Mayordomo Executus, los jefes opcionales de Zul'Gurub), dadores de misiones de la Horda en el lugar correcto, y las misiones de varias mazmorras las nombran todas." },
      { kind = "change",
        deDE = "Dungeonquests: Der Quest-Check beim Betreten einer Instanz gibt es jetzt auch in Classic Era, und die WoW-Forever-Dungeons kennen ihre Quests vollständiger.",
        enUS = "Dungeon quests: the quest check when entering an instance now also works in Classic Era, and WoW Forever dungeons know their quests more completely.",
        frFR = "Quêtes de donjon : la vérification des quêtes à l'entrée d'une instance fonctionne désormais aussi dans Classic Era, et les donjons de WoW Forever connaissent leurs quêtes plus complètement.",
        esES = "Misiones de mazmorra: la comprobación de misiones al entrar en una instancia ahora también funciona en Classic Era, y las mazmorras de WoW Forever conocen sus misiones de forma más completa." },
      { kind = "change",
        deDE = "Classic Era und WoW Forever: Boss- und Dungeoneingangs-Tooltips zeigen deutlich mehr seltene und epische Drops, auch von Endbossen wie Edwin van Cleef.",
