        frFR = "Classic Era et WoW Forever : les infobulles des boss et des entrées de donjon affichent bien plus d'objets rares et épiques, y compris des boss de fin comme Edwin VanCleef.",
        esES = "Classic Era y WoW Forever: los tooltips de jefes y de entradas de mazmorra muestran muchos más objetos raros y épicos, también de jefes finales como Edwin VanCleef." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Auch normale Dungeon- und Schlachtzugsgegner zeigen ihre gefährlichen Fähigkeiten mit Tipp im Tooltip.",
        enUS = "Classic Era and WoW Forever: regular dungeon and raid enemies also show their dangerous abilities with a tip in the tooltip.",
        frFR = "Classic Era et WoW Forever : les ennemis normaux de donjon et de raid affichent aussi leurs techniques dangereuses avec un conseil dans l'infobulle.",
        esES = "Classic Era y WoW Forever: los enemigos normales de mazmorras y bandas también muestran sus habilidades peligrosas con un consejo en el tooltip." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Der Tooltip von Dungeon- und Schlachtzugsbossen zeigt bis zu drei wichtige Fähigkeiten mit einem kurzen Tipp.",
        enUS = "Classic Era and WoW Forever: the tooltip of dungeon and raid bosses shows up to three important abilities with a short tip.",
        frFR = "Classic Era et WoW Forever : l'infobulle des boss de donjon et de raid affiche jusqu'à trois techniques importantes avec un court conseil.",
        esES = "Classic Era y WoW Forever: el tooltip de los jefes de mazmorras y bandas muestra hasta tres habilidades importantes con un breve consejo." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Gegenstände (und auf englischen Clients Objekte), die eine Dungeonquest oder Vorquest starten, nennen sie im Tooltip.",
        enUS = "Classic Era and WoW Forever: items (and on English clients objects) that start a dungeon quest or prequest name it in their tooltip.",
        frFR = "Classic Era et WoW Forever : les objets (et sur les clients anglais les objets du monde) qui lancent une quête de donjon ou une quête préalable l'indiquent dans leur infobulle.",
        esES = "Classic Era y WoW Forever: los objetos (y en clientes en inglés los objetos del mundo) que inician una misión de mazmorra o una misión previa la indican en su tooltip." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Dungeonquest-Geber in deiner Nähe erscheinen auf der Minimap, auch hinter der Zonengrenze; entfernte blass am Rand.",
        enUS = "Classic Era and WoW Forever: nearby dungeon quest givers show on the minimap, even across the zone border; distant ones faded at the edge.",
        frFR = "Classic Era et WoW Forever : les donneurs de quêtes de donjon proches apparaissent sur la minicarte, même au-delà de la limite de zone ; les plus lointains en pâle au bord.",
        esES = "Classic Era y WoW Forever: los dadores de misiones de mazmorra cercanos aparecen en el minimapa, incluso al otro lado del límite de zona; los lejanos, tenues en el borde." },
      { kind = "change",
        deDE = "Würfelkarte: Jeder Gegenstand hat sein Symbol; Drüberfahren am Symbol oder Namen zeigt die Gegenstandsinfo.",
        enUS = "Loot roll card: every item shows its icon; hovering the icon or name shows the item tooltip.",
        frFR = "Carte de jet de butin : chaque objet affiche son icône ; survoler l'icône ou le nom affiche l'infobulle de l'objet.",
        esES = "Tarjeta de tiradas de botín: cada objeto muestra su icono; pasar el ratón por el icono o el nombre muestra la información del objeto." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Nimmst du eine Dungeonquest an, zeigt ein kleines Fenster, wo es die übrigen Quests der Instanz und die nächsten Kettenschritte gibt; ein Klick setzt einen Kartenpunkt.",
