      { kind = "new",
        deDE = "Kartensymbole (Questgeber, Dungeon-Eingänge, Tode) erscheinen auch auf Nachbarzonen und der Kontinentkarte, behalten beim Zoomen ihre Größe und funktionieren mit OpenMap und Leatrix Maps.",
        enUS = "Map icons (quest givers, dungeon entrances, deaths) also show on neighboring zones and the continent map, keep their size when zooming and work with OpenMap and Leatrix Maps.",
        frFR = "Les icônes de carte (donneurs de quêtes, entrées de donjon, morts) apparaissent aussi sur les zones voisines et la carte du continent, gardent leur taille au zoom et fonctionnent avec OpenMap et Leatrix Maps.",
        esES = "Los iconos del mapa (dadores de misiones, entradas de mazmorra, muertes) también aparecen en las zonas vecinas y en el mapa del continente, mantienen su tamaño al hacer zoom y funcionan con OpenMap y Leatrix Maps." },
      { kind = "new",
        deDE = "Dungeon-Beute-Vorschau: Bosszeilen im Run-Fenster und die Dungeon-Eingänge auf der Karte zeigen die bekannten Drops ab rar (Classic Era und WoW Forever).",
        enUS = "Dungeon loot preview: boss rows in the runs window and dungeon entrances on the map show the known drops of rare quality or better (Classic Era and WoW Forever).",
        frFR = "Aperçu du butin : les lignes de boss de la fenêtre des runs et les entrées de donjon sur la carte affichent les objets connus de qualité rare ou mieux (Classic Era et WoW Forever).",
        esES = "Vista previa del botín: las filas de jefes de la ventana de partidas y las entradas de mazmorra en el mapa muestran los objetos conocidos de calidad rara o superior (Classic Era y WoW Forever)." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Vorquests, die zu einer Dungeonquest führen, zeigen Instanz und Schritt („[DT 2/7]“, „Führt zu … (Schritt 2/7)“) im Questlog, im Tooltip und beim Questgeber.",
        enUS = "Classic Era and WoW Forever: prequests leading to a dungeon quest show the instance and step (\"[DT 2/7]\", \"Leads to … (step 2/7)\") in the quest log, in the tooltip and at the quest giver.",
        frFR = "Classic Era et WoW Forever : les quêtes préalables menant à une quête de donjon affichent l'instance et l'étape (« [DT 2/7] », « Mène à … (étape 2/7) ») dans le journal de quêtes, l'infobulle et chez le donneur de quêtes.",
        esES = "Classic Era y WoW Forever: las misiones previas que llevan a una misión de mazmorra muestran la instancia y el paso («[DT 2/7]», «Lleva a … (paso 2/7)») en el registro de misiones, el tooltip y el dador de misiones." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: Dungeonquests tragen im Questlog, beim Questgeber und im Tracker den farbigen Kurznamen der Instanz, Quest-Tooltips die Zeile „Dungeon: Name“.",
        enUS = "Classic Era and WoW Forever: dungeon quests show the instance's colored short name in the quest log, at the quest giver and in the tracker, and quest tooltips a \"Dungeon: name\" line.",
        frFR = "Classic Era et WoW Forever : les quêtes de donjon affichent le nom court coloré de l'instance dans le journal de quêtes, chez le donneur de quêtes et dans le suivi, et les infobulles de quête la ligne « Donjon : nom ».",
        esES = "Classic Era y WoW Forever: las misiones de mazmorra muestran el nombre corto coloreado de la instancia en el registro de misiones, en el dador de misiones y en el seguimiento, y los tooltips de misión la línea «Mazmorra: nombre»." },
      { kind = "new",
        deDE = "Classic Era und WoW Forever: NPCs mit einer Dungeonquest, die du jetzt annehmen kannst, tragen ein Dungeon-Symbol an Namensplakette und Ziel, eine Tooltipzeile und einen Punkt auf der Karte.",
        enUS = "Classic Era and WoW Forever: NPCs with a dungeon quest you can take right now show a dungeon icon on their nameplate and target frame, a tooltip line and a map pin.",
        frFR = "Classic Era et WoW Forever : les PNJ ayant une quête de donjon que vous pouvez prendre maintenant affichent une icône de donjon sur leur barre de nom et la cible, une ligne d'infobulle et un repère sur la carte.",
        esES = "Classic Era y WoW Forever: los PNJ con una misión de mazmorra que puedes aceptar ahora muestran un icono de mazmorra en su placa de nombre y en el objetivo, una línea en el tooltip y un punto en el mapa." },
      { kind = "new",
        deDE = "Dungeon-Runs: Bosse und Rare erscheinen mit kleinem 3D-Porträt im Run-Fenster, der Endboss groß im Kopf, der Live-Tracker zeigt den nächsten Boss (Classic Era und WoW Forever).",
        enUS = "Dungeon runs: bosses and rares show a small 3D portrait in the runs window, the final boss a large one in the header, and the live tracker shows the next boss (Classic Era and WoW Forever).",
        frFR = "Donjons : les boss et rares affichent un petit portrait 3D dans la fenêtre des runs, le boss final en grand dans l'en-tête, et le suivi en direct montre le prochain boss (Classic Era et WoW Forever).",
        esES = "Mazmorras: jefes y raros muestran un pequeño retrato 3D en la ventana de partidas, el jefe final uno grande en la cabecera y el seguimiento en vivo muestra el siguiente jefe (Classic Era y WoW Forever)." },
      { kind = "new",
        deDE = "Neue Statistik Beutewert: Wert deiner Beute (Auctionator-Preis, sonst Händlerpreis) und Gold/h inklusive Beute, auch als Spalte in der Session-Historie.",
        enUS = "New statistic Loot value: the value of your loot (Auctionator price, otherwise vendor price) and gold/h including loot, also as a column in the session history.",
        frFR = "Nouvelle statistique Valeur du butin : la valeur de votre butin (prix Auctionator, sinon prix du marchand) et l'or/h butin compris, aussi en colonne dans l'historique des sessions.",
